// Independent check of the solver: for positions reached by random play from the opening, the
// value in the table must follow from its children's values, with the children generated by the
// JavaScript engine (not by the solver). Usage: node check_table.mjs table.bin [games]
import { initialState, legalMoves, step } from '../engine.js';
import { loadTable, index, kind, plies } from './table.mjs';

const T = loadTable(process.argv[2]);
const games = +(process.argv[3] || 3000);
let seed = 12345;
const rnd = (n) => { seed = (seed * 1103515245 + 12345) >>> 0; return seed % n; };

let checked = 0, bad = 0;
const counts = { win: 0, loss: 0, draw: 0 };
function check(s) {
  const v = T[index(s)];
  const kids = legalMoves(s).map((m) => {
    const c = step(s, m);
    const w = T[index(c)];
    if (c.winner === s.turn && w !== 1) bad++;
    if (c.winner === 1 - s.turn && w !== 2) bad++;
    if (c.winner === null && (w === 1 || w === 2)) bad++;
    return w;
  });
  let ok;
  if (v === 0) ok = !kids.some((w) => w & 1) && kids.some((w) => w === 0);
  else if (v & 1) ok = kids.every((w) => w && !(w & 1)) && Math.max(...kids.map(plies)) === plies(v) - 1;
  else ok = kids.some((w) => w & 1 && plies(w) === plies(v) - 1) && !kids.some((w) => w & 1 && plies(w) < plies(v) - 1);
  checked++; counts[kind(v)]++;
  if (!ok) { bad++; if (bad < 5) console.log('mismatch', s.cfg, s.turn, s.ban, v, kids); }
}
for (let g = 0; g < games; g++) {
  let s = initialState();
  for (let ply = 0; ply < 120 && s.winner === null; ply++) {
    check(s);
    const ms = legalMoves(s);
    s = { ...step(s, ms[rnd(ms.length)]) };
  }
}
console.log(`checked ${checked} positions (win ${counts.win}, loss ${counts.loss}, draw ${counts.draw}); mismatches ${bad}`);
console.log('opening, Mint to move:', kind(T[index(initialState())]));
process.exitCode = bad ? 1 : 0;
